SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1. Table: users
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `username` VARCHAR(50) NOT NULL UNIQUE,
  `password` VARCHAR(255) NOT NULL,
  `name` VARCHAR(100) DEFAULT 'Administrator',
  `role` VARCHAR(20) DEFAULT 'admin',
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE `password`=VALUES(`password`);

-- 2. Table: products (image column is LONGTEXT to support Base64 data and direct uploads)
DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `ref` VARCHAR(50) NOT NULL,
  `category` VARCHAR(50) NOT NULL,
  `subCategory` VARCHAR(100) NOT NULL,
  `title` VARCHAR(150) NOT NULL,
  `material` VARCHAR(150) NOT NULL,
  `image` LONGTEXT NOT NULL,
  `note` VARCHAR(150) DEFAULT 'Ukuran umum & custom',
  `sort_order` INT DEFAULT 0,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Table: blogs (image column is LONGTEXT to support Base64 data and direct uploads)
DROP TABLE IF EXISTS `blogs`;
CREATE TABLE `blogs` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `slug` VARCHAR(150) NOT NULL UNIQUE,
  `title` VARCHAR(255) NOT NULL,
  `date` DATE NOT NULL,
  `image` LONGTEXT NOT NULL,
  `category` VARCHAR(100) NOT NULL,
  `tags` TEXT NOT NULL,
  `author` VARCHAR(100) DEFAULT 'Admin',
  `views` INT DEFAULT 0,
  `summary` TEXT NOT NULL,
  `content` LONGTEXT NOT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

